```javascript
// ==================== VALIDATION ====================

/**
 * Validates the main order payload structure
 */
function validateOrderPayload(orderPayload) {
  if (!orderPayload || !orderPayload.userId || !Array.isArray(orderPayload.items) || orderPayload.items.length === 0) {
    return { valid: false, code: 'INVALID_PAYLOAD', error: 'User ID and items array required' };
  }
  return { valid: true };
}

/**
 * Validates each item in the order
 */
function validateOrderItems(items) {
  for (const it of items) {
    if (!it.sku || typeof it.qty !== 'number' || it.qty <= 0 || typeof it.price !== 'number' || it.price < 0) {
      return { valid: false, code: 'INVALID_ITEM', error: `Invalid item: ${JSON.stringify(it)}` };
    }
  }
  return { valid: true };
}

// ==================== CALCULATIONS ====================

/**
 * Calculates subtotal from order items
 */
function calculateSubtotal(items) {
  let subtotal = 0;
  for (const it of items) {
    subtotal += it.price * it.qty;
  }
  return subtotal;
}

/**
 * Calculates discount based on coupon code
 */
async function calculateDiscount(subtotal, couponCode, db) {
  let discount = 0;
  if (couponCode) {
    const coupon = await db.collection('coupons').findOne({ code: couponCode, active: true });
    if (coupon) {
      if (coupon.type === 'percent') {
        discount = subtotal * (coupon.amount / 100);
      } else if (coupon.type === 'fixed') {
        discount = Math.min(subtotal, coupon.amount);
      }
    }
  }
  return discount;
}

/**
 * Calculates tax based on shipping state
 */
function calculateTax(taxableAmount, state) {
  const taxRate = state === 'CA' ? 0.0925 : 0.05;
  return taxableAmount * taxRate;
}

/**
 * Calculates shipping cost based on subtotal
 */
function calculateShipping(subtotal) {
  return subtotal > 100 ? 0 : 9.99;
}

/**
 * Calculates final total with rounding
 */
function calculateTotal(taxableAmount, tax, shipping) {
  return Math.round((taxableAmount + tax + shipping) * 100) / 100;
}

// ==================== INVENTORY ====================

/**
 * Checks inventory availability for all items
 */
async function checkInventory(items, db) {
  for (const it of items) {
    const inv = await db.collection('inventory').findOne({ sku: it.sku });
    if (!inv || inv.stock < it.qty) {
      return { available: false, code: 'OUT_OF_STOCK', error: `Out of stock for ${it.sku}` };
    }
  }
  return { available: true };
}

/**
 * Updates inventory stock for all items
 */
async function updateInventory(items, db) {
  for (const it of items) {
    await db.collection('inventory').updateOne({ sku: it.sku }, { $inc: { stock: -it.qty } });
  }
}

// ==================== PAYMENT ====================

/**
 * Processes payment through payment gateway
 */
async function processPayment(orderPayload, total, paymentGateway) {
  try {
    const paymentResult = await paymentGateway.charge({
      customerId: orderPayload.userId,
      amount: Math.round(total * 100),
      currency: 'usd',
      idempotencyKey: orderPayload.idempotencyKey,
    });
    return { success: true, chargeId: paymentResult.chargeId };
  } catch (err) {
    return { success: false, code: 'PAYMENT_FAILED', error: err.message };
  }
}

// ==================== ORDER RECORD ====================

/**
 * Creates order record object
 */
function createOrderRecord(orderPayload, subtotal, discount, tax, shipping, total, chargeId) {
  return {
    userId: orderPayload.userId,
    items: orderPayload.items,
    subtotal,
    discount,
    tax,
    shipping,
    total,
    chargeId,
    createdAt: new Date(),
    status: 'PAID',
  };
}

/**
 * Saves order record to database
 */
async function saveOrder(orderRecord, db) {
  return await db.collection('orders').insertOne(orderRecord);
}

// ==================== EMAIL ====================

/**
 * Sends order confirmation email
 */
async function sendConfirmationEmail(orderPayload, orderId, total, emailClient) {
  try {
    await emailClient.send({
      to: orderPayload.customerEmail,
      subject: `Order Confirmation #${orderId}`,
      body: `Thank you for your order of $${total.toFixed(2)}.`,
    });
  } catch (emailErr) {
    console.error('Failed to send confirmation email', emailErr);
  }
}

// ==================== MAIN ORCHESTRATION ====================

/**
 * Main order processing function - orchestrates all steps
 */
async function processOrder(orderPayload, db, paymentGateway, emailClient) {
  // Step 1: Validate payload
  const payloadValidation = validateOrderPayload(orderPayload);
  if (!payloadValidation.valid) {
    return { success: false, code: payloadValidation.code, error: payloadValidation.error };
  }

  // Step 2: Validate items
  const itemsValidation = validateOrderItems(orderPayload.items);
  if (!itemsValidation.valid) {
    return { success: false, code: itemsValidation.code, error: itemsValidation.error };
  }

  // Step 3: Calculate subtotal
  const subtotal = calculateSubtotal(orderPayload.items);

  // Step 4: Calculate discount
  const discount = await calculateDiscount(subtotal, orderPayload.couponCode, db);

  // Step 5: Calculate tax
  const taxable = Math.max(0, subtotal - discount);
  const tax = calculateTax(taxable, orderPayload.shippingAddress?.state);

  // Step 6: Calculate shipping
  const shipping = calculateShipping(subtotal);

  // Step 7: Calculate total
  const total = calculateTotal(taxable, tax, shipping);

  // Step 8: Check inventory
  const inventoryCheck = await checkInventory(orderPayload.items, db);
  if (!inventoryCheck.available) {
    return { success: false, code: inventoryCheck.code, error: inventoryCheck.error };
  }

  // Step 9: Process payment
  const paymentResult = await processPayment(orderPayload, total, paymentGateway);
  if (!paymentResult.success) {
    return { success: false, code: paymentResult.code, error: paymentResult.error };
  }

  // Step 10: Create and save order record
  const orderRecord = createOrderRecord(
    orderPayload,
    subtotal,
    discount,
    tax,
    shipping,
    total,
    paymentResult.chargeId
  );
  const insertResult = await saveOrder(orderRecord, db);

  // Step 11: Update inventory
  await updateInventory(orderPayload.items, db);

  // Step 12: Send confirmation email
  await sendConfirmationEmail(orderPayload, insertResult.insertedId, total, emailClient);

  // Return success response
  return { success: true, orderId: insertResult.insertedId, total };
}

// Export all functions for testing and reuse
module.exports = {
  processOrder,
  validateOrderPayload,
  validateOrderItems,
  calculateSubtotal,
  calculateDiscount,
  calculateTax,
  calculateShipping,
  calculateTotal,
  checkInventory,
  updateInventory,
  processPayment,
  createOrderRecord,
  saveOrder,
  sendConfirmationEmail,
};
```

