# Auth Module Flow Trace & Security Analysis

## 🔄 Full Request Flow Trace

### 1. Login Request Flow

```
Client → POST /login {username, password}
    ↓
handleLogin()
    ↓
1. Extract credentials from req.body
2. Find user in userDb (plain text comparison)
3. Generate 16-byte random token (32 hex chars)
4. Store session in Map: token → {userId, role, created}
5. Set cookie: session={token}; Path=/
6. Return: {success: true, user: {id, username}}
    ↓
Client stores cookie, sends with subsequent requests
```

### 2. Session Validation Flow

```
Client → GET /protected (with cookie)
    ↓
validateSession() middleware
    ↓
1. Extract cookie header
2. Parse session token via regex
3. Look up session in Map
4. Attach session to req.user
5. Call next()
    ↓
Protected route handler accesses req.user
```

---

## ⚠️ Identified Weaknesses (Ranked by Severity)

| # | Weakness | Severity | Impact |
|---|----------|----------|--------|
| 1 | **Plain text password comparison** | 🔴 Critical | DB leak = all passwords exposed |
| 2 | **No session expiration** | 🔴 Critical | Sessions last forever |
| 3 | **Missing cookie security flags** | 🔴 Critical | XSS, MITM, CSRF attacks |
| 4 | **No CSRF protection** | 🔴 Critical | Cross-site request forgery |
| 5 | **Memory-based sessions** | 🟠 High | No cleanup, no scaling |
| 6 | **No rate limiting** | 🟠 High | Brute force attacks |
| 7 | **No password hashing** | 🟠 High | Timing attacks, DB exposure |
| 8 | **No logout mechanism** | 🟡 Medium | Sessions persist indefinitely |
| 9 | **No token regeneration** | 🟡 Medium | Session fixation possible |
| 10 | **No concurrent session limits** | 🟡 Medium | Multiple sessions per user |
| 11 | **No timing attack protection** | 🟡 Medium | Username enumeration |
| 12 | **No session invalidation on password change** | 🟡 Medium | Old sessions remain valid |
| 13 | **No distributed session support** | 🟡 Medium | Single server only |
| 14 | **No logging/auditing** | 🟢 Low | Hard to track attacks |
| 15 | **No error message leakage** | 🟢 Low | Could reveal username existence |

---

## 🛠️ Improved Implementation

```javascript
// authService.js
import crypto from 'crypto';
import bcrypt from 'bcrypt';
import { randomUUID } from 'crypto';

const SESSION_DURATION = 24 * 60 * 60 * 1000; // 24 hours
const MAX_SESSIONS_PER_USER = 5;
const SESSION_CLEANUP_INTERVAL = 60 * 60 * 1000; // 1 hour
const RATE_LIMIT_WINDOW = 60 * 1000; // 1 minute
const MAX_LOGIN_ATTEMPTS = 5;

const sessions = new Map();
const loginAttempts = new Map();
let cleanupInterval = null;

// Start session cleanup
function startSessionCleanup() {
  cleanupInterval = setInterval(() => {
    const now = Date.now();
    for (const [token, session] of sessions.entries()) {
      if (now - session.created > SESSION_DURATION) {
        sessions.delete(token);
      }
    }
  }, SESSION_CLEANUP_INTERVAL);
}

// Secure timing-safe comparison
function timingSafeEqual(a, b) {
  if (typeof a !== 'string' || typeof b !== 'string') return false;
  if (a.length !== b.length) return false;
  let result = 0;
  for (let i = 0; i < a.length; i++) {
    result |= a.charCodeAt(i) ^ b.charCodeAt(i);
  }
  return result === 0;
}

// Check rate limit
function checkRateLimit(ip) {
  const now = Date.now();
  const attempts = loginAttempts.get(ip) || { count: 0, reset: now + RATE_LIMIT_WINDOW };

  if (now > attempts.reset) {
    loginAttempts.set(ip, { count: 0, reset: now + RATE_LIMIT_WINDOW });
    return true;
  }

  if (attempts.count >= MAX_LOGIN_ATTEMPTS) {
    return false;
  }

  attempts.count++;
  loginAttempts.set(ip, attempts);
  return true;
}

// Hash password
export async function hashPassword(password, saltRounds = 12) {
  return bcrypt.hash(password, saltRounds);
}

// Verify password
export async function verifyPassword(password, hash) {
  return bcrypt.compare(password, hash);
}

export async function handleLogin(req, res, userDb) {
  const { username, password } = req.body;
  const clientIp = req.ip || req.connection?.remoteAddress;

  // Rate limiting
  if (!checkRateLimit(clientIp)) {
    return res.status(429).json({ error: 'Too many login attempts' });
  }

  // Validate input
  if (!username || !password) {
    return res.status(400).json({ error: 'Username and password required' });
  }

  // Find user
  const user = userDb.find(u => u.username === username);

  // Use timing-safe comparison to prevent username enumeration
  const passwordMatch = user ? await verifyPassword(password, user.password) : false;

  if (!user || !passwordMatch) {
    return res.status(401).json({ error: 'Invalid credentials' });
  }

  // Check concurrent sessions
  const userSessions = Array.from(sessions.values()).filter(
    s => s.userId === user.id
  );
  if (userSessions.length >= MAX_SESSIONS_PER_USER) {
    // Invalidate oldest session
    const oldest = userSessions.sort((a, b) => a.created - b.created)[0];
    sessions.delete(oldest.token);
  }

  // Generate secure session token
  const token = randomUUID();
  const now = Date.now();

  // Store session
  sessions.set(token, {
    userId: user.id,
    username: user.username,
    role: user.role,
    created: now,
    expires: now + SESSION_DURATION,
    ip: clientIp,
    userAgent: req.headers['user-agent'] || null
  });

  // Set secure cookie
  res.setHeader('Set-Cookie', `session=${token}; Path=/; HttpOnly; Secure; SameSite=Strict; Max-Age=${SESSION_DURATION / 1000}`);

  // Clear rate limit on success
  loginAttempts.delete(clientIp);

  return res.json({
    success: true,
    user: { id: user.id, username: user.username }
  });
}

export function validateSession(req, res, next) {
  const cookieHeader = req.headers.cookie || '';
  const match = cookieHeader.match(/session=([a-f0-9-]+)/);

  if (!match) {
    return res.status(401).json({ error: 'No session' });
  }

  const token = match[1];
  const session = sessions.get(token);

  if (!session) {
    return res.status(401).json({ error: 'Invalid session' });
  }

  // Check expiration
  if (Date.now() > session.expires) {
    sessions.delete(token);
    return res.status(401).json({ error: 'Session expired' });
  }

  // Optional: IP/User-Agent binding (can be relaxed for mobile)
  // if (session.ip && session.ip !== req.ip) {
  //   return res.status(401).json({ error: 'Session IP mismatch' });
  // }

  // Attach session to request
  req.user = {
    id: session.userId,
    username: session.username,
    role: session.role,
    sessionId: token
  };

  next();
}

export async function handleLogout(req, res) {
  const cookieHeader = req.headers.cookie || '';
  const match = cookieHeader.match(/session=([a-f0-9-]+)/);

  if (match) {
    sessions.delete(match[1]);
  }

  res.setHeader('Set-Cookie', 'session=; Path=/; HttpOnly; Secure; SameSite=Strict; Max-Age=0');
  return res.json({ success: true });
}

export function invalidateUserSessions(userId, userDb) {
  // Invalidate all sessions for a user (e.g., on password change)
  for (const [token, session] of sessions.entries()) {
    if (session.userId === userId) {
      sessions.delete(token);
    }
  }
}

export function getSessionStats() {
  const now = Date.now();
  const activeSessions = Array.from(sessions.values()).filter(
    s => s.expires > now
  );

  return {
    totalSessions: sessions.size,
    activeSessions: activeSessions.length,
    expiredSessions: sessions.size - activeSessions.length
  };
}

export function cleanup() {
  if (cleanupInterval) {
    clearInterval(cleanupInterval);
  }
  sessions.clear();
  loginAttempts.clear();
}

// Initialize cleanup on module load
startSessionCleanup();
```

