## 🧪 Usage Example

```javascript
// server.js
import express from 'express';
import { 
  handleLogin, 
  validateSession, 
  handleLogout, 
  hashPassword,
  cleanup 
} from './authService.js';

const app = express();
app.use(express.json());

// Sample user database (passwords should be hashed)
