import { Pool } from 'pg';

// Use connection pooling to handle concurrent requests efficiently
export const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  max: 20, // Limit connections for small DB instance
  idleTimeoutMillis: 30000,
  connectionTimeoutMillis: 2000,
});

export const query = async (text: string, params?: any[]) => {
  const start = Date.now();
  const res = await pool.query(text, params);
  const duration = Date.now() - start;
  console.log('Executed query', { text, duration, rows: res.rowCount });
  return res;
};
```

### 3.3. `src/auth.ts` (Middleware & Validation)
```typescript
import { Request, Response, NextFunction } from 'express';
import jwt from 'jsonwebtoken';

// Extend Express Request to include user info
declare global {
  namespace Express {
    interface Request {
      user?: { id: string; email: string; role: string };
    }
  }
}

// Middleware to verify JWT from Supabase/Custom Auth
export const authenticate = async (req: Request, res: Response, next: NextFunction) => {
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'Missing token' });
  }

  const token = authHeader.split(' ')[1];
  try {
    // In production, use Supabase's verifyJWT or your own secret
    const secret = process.env.JWT_SECRET || 'fallback-secret';
    const decoded = jwt.verify(token, secret) as any;
    req.user = decoded;
    next();
  } catch (err) {
    return res.status(403).json({ error: 'Invalid token' });
  }
};
```

### 3.4. `src/billing.ts` (Stripe Integration)
```typescript
import Stripe from 'stripe';
import { query } from './db';

const stripe = new Stripe(process.env.STRIPE_SECRET_KEY!, { apiVersion: '2023-10-16' });

export const createCheckoutSession = async (userId: string, priceId: string) => {
  const session = await stripe.checkout.sessions.create({
    payment_method_types: ['card'],
    line_items: [{ price: priceId, quantity: 1 }],
    mode: 'subscription',
    success_url: `${process.env.FRONTEND_URL}/success?session_id={CHECKOUT_SESSION_ID}`,
    cancel_url: `${process.env.FRONTEND_URL}/cancel`,
    metadata: { userId },
  });
  return session.url;
};

export const handleWebhook = async (event: Stripe.Event) => {
  const session = event.data.object as Stripe.Checkout.Session;

  if (event.type === 'checkout.session.completed') {
    const userId = session.metadata?.userId;
    const subscriptionId = session.subscription as string;

    // Update user status in DB
    await query(
      `UPDATE users SET subscription_id = $1, status = 'active' WHERE id = $2`,
      [subscriptionId, userId]
    );
  } else if (event.type === 'customer.subscription.deleted') {
    const subscriptionId = event.data.object.id as string;
    await query(
      `UPDATE users SET status = 'inactive', subscription_id = NULL WHERE subscription_id = $1`,
      [subscriptionId]
    );
  }
};
```

### 3.5. `src/routes.ts` (REST API Endpoints)
```typescript
import { Router, Request, Response } from 'express';
import { query } from './db';
import { authenticate } from './auth';
import { createCheckoutSession, handleWebhook } from './billing';
import crypto from 'crypto';

const router = Router();

// 1. Protected Resource: Get User Data
router.get('/me', authenticate, async (req: Request, res: Response) => {
  try {
    const { rows } = await query(
      'SELECT id, email, status, subscription_id FROM users WHERE id = $1',
      [req.user!.id]
    );
    if (rows.length === 0) return res.status(404).json({ error: 'User not found' });
    res.json(rows[0]);
  } catch (err) {
    res.status(500).json({ error: 'Database error' });
  }
});

// 2. Billing: Create Checkout
router.post('/billing/checkout', authenticate, async (req: Request, res: Response) => {
  try {
    const { priceId } = req.body;
    if (!priceId) return res.status(400).json({ error: 'Price ID required' });

    const url = await createCheckoutSession(req.user!.id, priceId);
    res.json({ url });
  } catch (err) {
    res.status(500).json({ error: 'Billing error' });
  }
});

// 3. Stripe Webhook Endpoint
router.post('/webhook', (req: Request, res: Response) => {
  const sig = req.headers['stripe-signature']!;
  const endpointSecret = process.env.STRIPE_WEBHOOK_SECRET!;

  let event: Stripe.Event;

  try {
    event = stripe.webhooks.constructEvent(req.body, sig, endpointSecret);
  } catch (err) {
    return res.status(400).send(`Webhook Error: ${err.message}`);
  }

  handleWebhook(event).then(() => res.json({ received: true }));
});

export default router;
```

### 3.6. `src/index.ts` (Server Entry Point)
